 * @returns {void}
 * @hidden N
 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf40000.btn_delRow_onclick' }); }
