/**
 * @method
 * @name btn_doSave_onclick
 * @description btn_doSave 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_doSave_onclick = async function(e){
    try {
        await scwin.doSave()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf40000.btn_doSave_onclick' }); }
